const paths=['sikdae','welfare','bizgift','coffee','delivery','vendingmachine','foodtruck','benefitmall','quick','compulsory','message','equipment'];services.forEach((s,i)=>s.path=paths[i]);
const officialIcons=['fa-thin fa-ticket','fa-thin fa-hand-holding-heart','fa-thin fa-gifts','fa-kit fa-coffee','fa-thin fa-motorcycle','fa-kit fa-japangi','fa-kit fa-foodtruck','fa-thin fa-badge-percent','fa-thin fa-box','fa-thin fa-graduation-cap','fa-kit fa-message','fa-kit fa-office'];
const officialImages=['service-sikdae.jpg','service-welfare.jpg','service-bizgift.jpg','service-coffee.png','service-delivery.jpg','service-vendingmachine.png','service-foodtruck.png',null,'service-quick.jpg','service-compulsory.jpg','service-message.png','service-equipment.png'];services.forEach((s,i)=>{s.icon=officialIcons[i];s.image=officialImages[i]});
const labels={food:'식사·간식',benefit:'복지·선물',office:'오피스 운영'};let selectedService=services[0];
const grid=document.querySelector('#service-grid');function renderServices(filter='all'){grid.replaceChildren();services.filter(s=>filter==='all'||s.cat===filter).forEach(s=>{const button=document.createElement('button');button.className='service-card';button.innerHTML=`<span class="arrow">↗</span>${s.image?`<img class="service-photo" src="assets/official/${s.image}" alt="${s.name} 공식 소개 이미지" loading="lazy">`:""}<span class="service-icon" aria-hidden="true"><i class="${s.icon}"></i></span><small>${labels[s.cat]}</small><h3>${s.name}</h3><p>${s.desc}</p>`;button.setAttribute('aria-label',s.name+' 서비스 자세히 보기');button.addEventListener('click',()=>openService(s));grid.append(button);});}renderServices();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderServices(b.dataset.filter)}));
function openService(s){location.href=s.path+'.html'}
const days=[['COFFEE & A FRESH START','좋은 아침은<br>한 잔의 여유에서.','커피머신부터 원두까지, 우리 사무실에 맞는 커피 환경을 준비하세요.','커피대장',3,'0%'],['LUNCH & A LITTLE HAPPINESS','오늘의 점심이<br>기다려지도록.','먹고 싶은 메뉴를 고르고, 모바일로 간편하게. 매일의 한 끼가 좋은 복지가 됩니다.','식권대장',0,'35%'],['TAKE A LITTLE BREAK','잠깐 쉬어가는<br>시간도 맛있게.','가까운 곳에서 챙기는 음료와 간식. 직원의 일상에 작은 여유를 더해보세요.','매점대장',5,'65%'],['A GIFT, A THOUGHT','선물에 담는<br>고마운 마음.','함께해 준 직원에게 전하는 선물. 예산과 인원에 맞춰 플래너와 준비하세요.','단체선물대장',2,'100%']];
document.querySelectorAll('[data-day]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-day]').forEach(x=>x.setAttribute('aria-selected',x===b));const d=days[+b.dataset.day];document.querySelector('#moment-tag').textContent=d[0];document.querySelector('#moment-title').innerHTML=d[1];document.querySelector('#moment-desc').textContent=d[2];const l=document.querySelector('#moment-link');l.textContent=d[3]+' 살펴보기 ↗';l.onclick=e=>{e.preventDefault();openService(services[d[4]])};document.querySelector('#moment-image').style.objectPosition=d[5]+' center';}));document.querySelector('#moment-link').onclick=e=>{e.preventDefault();openService(services[3])};
const personaCopy={employee:'<h3>오늘 먹고 싶은 메뉴를, 자유롭게.</h3><p>근처 제휴점을 찾고, 지갑 없이 간편하게 결제하세요.<br>동료와 함께한 점심은 함께결제로 편리하게.</p><ul><li>다양한 제휴점과 메뉴</li><li>모바일로 간편한 식대 결제</li><li>동료와 1/N 함께결제</li></ul>',manager:'<h3>반복되는 식대 업무를, 간편하게.</h3><p>지급부터 내역 확인, 정산까지 한곳에서.<br>시간과 요일, 지급 기준은 회사 정책에 맞춰 설정하세요.</p><ul><li>즉시 지급과 예약 지급</li><li>사용 내역 자동 기록과 통계</li><li>여러 제휴점 이용도 통합 정산</li></ul>'};
document.querySelectorAll('[data-persona]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-persona]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelector('#persona-copy').innerHTML=personaCopy[b.dataset.persona];document.querySelector('#phone').hidden=b.dataset.persona!=='employee';document.querySelector('#dashboard').hidden=b.dataset.persona!=='manager';}));
document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-screen]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelector('#official-app-image').src='assets/official/sikdae-app-'+b.dataset.screen+'.png';}));
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('js-reveal');observer.observe(el)})}

document.querySelector('.ribbon-pause').addEventListener('click',e=>{const paused=document.querySelector('.benefit-ribbon').classList.toggle('is-paused');e.currentTarget.setAttribute('aria-pressed',paused);e.currentTarget.setAttribute('aria-label',paused?'띠배너 움직임 재생':'띠배너 움직임 멈추기');e.currentTarget.querySelector('span').textContent=paused?'▷':'Ⅱ';});

